import React, { useState, useEffect } from 'react';
import {
  Calendar,
  MapPin,
  Clock,
  Heart,
  ChevronDown,
  Music,
  Music2,
  Upload,
  Phone,
  Home,
  MailOpen
} from 'lucide-react';

function App() {
  const [activeTab, setActiveTab] = useState('home');
  const [isPlaying, setIsPlaying] = useState(false);
  const [isVisible, setIsVisible] = useState(true);

  const weddingDate = "September 8, 2024";
  const weddingTime = "12:30 PM";
  const locationAddress = "178/03, Welipitiya Road, Koledanda, Weligama, 81700";
  const contactNumber = "+94 77 148 3381";

  useEffect(() => {
    setIsVisible(true);
  }, [activeTab]);

  return (
    <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif">
      <section className="min-h-screen flex flex-col items-center justify-center text-center">
        <span className="text-[#D4AF37] uppercase tracking-widest text-xs mb-4">
          Together with their families
        </span>

        <h1 className="text-6xl md:text-8xl font-light italic">
          Shazeen <span className="text-[#D4AF37] mx-3">&</span> Shimra
        </h1>

        <p className="mt-6 text-xl italic opacity-70">
          Cordially invite you to celebrate their Fathiha Ceremony
        </p>

        <div className="mt-10">
          <p className="text-4xl text-[#D4AF37]">{weddingDate}</p>
          <p className="uppercase text-xs tracking-widest mt-2">
            At Our Residence
          </p>
        </div>
      </section>
    </div>
  );
}

export default App;
